import scala.io.StdIn

/** Acknowledged, closed-world bridge for the monitor generated by DejaVu. */
class SynchronousMonitor extends PropertyMonitor {
  var latestViolations: Vector[String] = Vector.empty

  override def recordResult(): Unit = ()

  override def evaluate(): Unit = {
    latestViolations = Vector.empty
    for (formula <- formulae) {
      formula.setTime(deltaTime)
      if (!formula.evaluate()) {
        errors += 1
        // DejaVu's base Formula derives `name` by splitting on underscores,
        // which collapses scoped IDs such as run_closeOnce to just "run".
        // Preserve the full generated class suffix for level-aware reports.
        val propertyId = formula.getClass.getSimpleName.stripPrefix("Formula_")
        latestViolations = latestViolations :+ propertyId
      }
    }
  }

  def step(name: String, args: List[Any], timestamp: Int): Vector[String] = synchronized {
    lineNr += 1
    setTime(timestamp)
    submit(name, args)
    latestViolations
  }
}

object SynchronousBridge {
  private val arities: Map[String, Int] = Map(
    "runStarted" -> 2,
    "activity" -> 3,
    "optimizerAskTellConfigured" -> 2,
    "optimizerOpaqueConfigured" -> 2,
    "firstIterationStarted" -> 5,
    "nextIterationStarted" -> 6,
    "parametersBound" -> 5,
    "termExpected" -> 6,
    "jobSubmitIntent" -> 6,
    "jobSubmitted" -> 7,
    "termObserved" -> 8,
    "measurementsSealed" -> 5,
    "numericValid" -> 6,
    "firstConvergenceChecked" -> 7,
    "nextConvergenceChecked" -> 9,
    "convergenceTrue" -> 5,
    "convergenceFalse" -> 5,
    "iterationPass" -> 5,
    "objectiveReleaseIntent" -> 5,
    "optimizerUpdateIntent" -> 5,
    "optimizerUpdated" -> 5,
    "opaqueOptimizerAdvanced" -> 5,
    "iterationLimitReached" -> 4,
    "iterationClosed" -> 8,
    "criticalFail" -> 5,
    "iterationAborted" -> 5,
    "runConverged" -> 5,
    "runMaxIterations" -> 5,
    "runOptimizerStopped" -> 5,
    "runAborted" -> 5,
    "runClosed" -> 2
  )

  private def clean(value: String): String =
    value.replace("\t", " ").replace("\r", " ").replace("\n", " ")

  def main(args: Array[String]): Unit = {
    val bits = if (args.nonEmpty) args(0).toInt else 24
    Options.BITS = bits
    Options.DEBUG = false
    Options.PROFILE = false
    Options.PRINT = false
    Options.STATISTICS = false
    val monitor = new SynchronousMonitor
    var lastSequence = 0L
    var runWasClosed = false
    println("RV1\tREADY")
    Console.out.flush()

    var keepRunning = true
    while (keepRunning) {
      val line = StdIn.readLine()
      if (line == null || line == "RV1\tCLOSE") {
        keepRunning = false
      } else {
        val fields = line.split("\t", -1).toList
        fields match {
          case "RV1" :: seqText :: event :: eventArgs =>
            try {
              val seq = seqText.toLong
              if (seq != lastSequence + 1 || seq > Int.MaxValue) {
                throw new IllegalArgumentException(
                  s"nonconsecutive sequence: expected ${lastSequence + 1}, got $seq"
                )
              }
              lastSequence = seq
              val schemaViolation = arities.get(event) match {
                case None => Some("run_event_schema")
                case Some(expected) if eventArgs.length != expected =>
                  Some("run_event_schema")
                case _ if runWasClosed => Some("run_terminal_absorbing")
                case _ => None
              }
              schemaViolation match {
                case Some(property) => println(s"RV1\t$seq\tFAIL\t$property")
                case None =>
                  val violations = monitor.step(event, eventArgs, seq.toInt)
                  if (violations.isEmpty) {
                    println(s"RV1\t$seq\tPASS")
                    if (event == "runClosed") runWasClosed = true
                  } else {
                    println(s"RV1\t$seq\tFAIL\t${violations.mkString("|")}")
                  }
              }
            } catch {
              case error: Throwable =>
                println(s"RV1\t${clean(seqText)}\tERROR\t${clean(error.toString)}")
            }
            Console.out.flush()
          case _ =>
            println("RV1\t0\tERROR\tmalformed request")
            Console.out.flush()
        }
      }
    }
  }
}
